'use client'

// Validation panel for the dashboard.
//
// Rendered natively from explorer/data/validation.json (generated by
// product/build_validation_card.py) rather than embedding the PNG, so it
// restyles with the dashboard, stays readable at any width, and every number
// traces to the same source of truth the slide figure uses.
//
// Colours were checked with the dataviz palette validator against the dashboard
// surface #27272A: #17a2b8 / #d95926 / #9085e9 pass the lightness band, chroma
// floor, CVD separation, normal-vision floor and contrast checks.
//
// Design intent: the caveats are NOT hidden behind a toggle. A validation panel
// that shows 0.829 prominently and buries "a quarry with no lithium scored
// higher" would be the exact overclaim this project avoids everywhere else.
//
// Layout: the root declares its own named container (`@container/vcard`) and every
// breakpoint below is keyed to THAT, not the viewport. The same component is
// mounted in the wide dashboard tab and in the Explorer's narrow, user-resizable
// rail; keying off the viewport would give four KPI columns inside a 380px rail
// simply because the window happened to be wide.

import { useEffect, useState } from 'react'
import {
  AlertTriangle, Download, ChevronDown, FlaskConical, ExternalLink, MapPin,
} from 'lucide-react'
import data from '../data/validation.json'

const C_DEPOSIT = '#17a2b8'
const C_DISTURBED = '#d95926'
const C_DESERT = '#9085e9'

const V = data as any
const M = V.metrics

function Stat({ label, value, sub, accent }: {
  label: string; value: string; sub?: string; accent?: string
}) {
  return (
    <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
      <p className="text-[11px] text-zinc-400">{label}</p>
      <p className="text-2xl font-semibold mt-1 leading-none"
         style={accent ? { color: accent } : undefined}>{value}</p>
      {sub && <p className="text-[11px] text-zinc-500 mt-1.5 leading-snug">{sub}</p>}
    </div>
  )
}

/** AUC with its bootstrap interval on a 0.5–1.0 scale. */
function AucRange() {
  const [lo, hi] = M.auc_ci as [number, number]
  const pos = (x: number) => ((x - 0.5) / 0.5) * 100
  return (
    <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
      <div className="flex items-baseline justify-between">
        <p className="text-[11px] text-zinc-400">Cross-scene ROC-AUC</p>
        <p className="text-[11px] text-zinc-500">95% CI, site bootstrap</p>
      </div>
      <p className="text-3xl font-semibold mt-1 leading-none" style={{ color: C_DEPOSIT }}>
        {M.auc}
      </p>

      <div className="relative h-8 mt-3">
        <div className="absolute inset-x-0 top-3 h-1 rounded-full bg-white/8" />
        {/* 0.5 = chance */}
        <div className="absolute top-1 h-5 w-px bg-white/25" style={{ left: '0%' }} />
        <div className="absolute top-2.5 h-2 rounded-full opacity-70"
             style={{ left: `${pos(lo)}%`, width: `${pos(hi) - pos(lo)}%`,
                      background: C_DEPOSIT }} />
        <div className="absolute top-1.5 h-4 w-[3px] rounded-full"
             style={{ left: `${pos(M.auc)}%`, background: C_DEPOSIT }} />
      </div>
      <div className="flex justify-between text-[11px] text-zinc-500">
        <span>0.5 — chance</span>
        <span className="text-zinc-400">{lo} – {hi}</span>
        <span>1.0</span>
      </div>
    </div>
  )
}

/** Raw-index distributions with every deposit marked. */
function Distribution() {
  const d = V.distribution
  const W = 560, H = 190, PAD_L = 8, PAD_B = 22
  const xs: number[] = d.bin_centres
  const x0 = xs[0], x1 = xs[xs.length - 1]
  const maxY = Math.max(...d.desert, ...d.disturbed, 0.001)
  const px = (v: number) => PAD_L + ((v - x0) / (x1 - x0)) * (W - PAD_L * 2)
  const py = (v: number) => H - PAD_B - (v / maxY) * (H - PAD_B - 10)
  const path = (ys: number[]) =>
    ys.map((y, i) => `${i ? 'L' : 'M'}${px(xs[i]).toFixed(1)},${py(y).toFixed(1)}`).join(' ')

  return (
    <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
      <p className="text-sm font-medium text-zinc-200">Where known deposits sit against background</p>
      <p className="text-[11px] text-zinc-500 mt-0.5 mb-2">
        Raw lithium index (B11/B12), before per-scene normalisation — the only form
        comparable across scenes.
      </p>

      <svg viewBox={`0 0 ${W} ${H}`} className="w-full" role="img"
           aria-label="Raw index distribution for desert controls and a disturbed quarry, with known deposits marked">
        <path d={`${path(d.desert)} L${px(x1)},${py(0)} L${px(x0)},${py(0)} Z`}
              fill={C_DESERT} fillOpacity="0.35" />
        <path d={path(d.desert)} stroke={C_DESERT} strokeWidth="1.5" fill="none" />
        <path d={path(d.disturbed)} stroke={C_DISTURBED} strokeWidth="2" fill="none" />

        {V.deposits.map((r: any) => (
          <g key={r.site}>
            <line x1={px(r.value)} x2={px(r.value)} y1={py(maxY) - 2} y2={H - PAD_B}
                  stroke={C_DEPOSIT} strokeWidth="2" />
            <circle cx={px(r.value)} cy={py(maxY) - 2} r="3" fill={C_DEPOSIT} />
            <title>{`${r.site} — ${r.value.toFixed(3)} (${r.maturity})`}</title>
          </g>
        ))}
        {V.brine.map((r: any) => (
          <line key={r.site} x1={px(r.value)} x2={px(r.value)} y1={py(maxY) + 14}
                y2={H - PAD_B} stroke="#8e9bab" strokeWidth="1.2" strokeDasharray="3 3">
            <title>{`${r.site} (brine — excluded)`}</title>
          </line>
        ))}

        <line x1={PAD_L} x2={W - PAD_L} y1={H - PAD_B} y2={H - PAD_B}
              stroke="#ffffff" strokeOpacity="0.15" />
        {[1.0, 1.2, 1.4, 1.6, 1.8, 2.0].map(t => (
          <text key={t} x={px(t)} y={H - 7} fontSize="9" fill="#8e9bab"
                textAnchor="middle">{t.toFixed(1)}</text>
        ))}
      </svg>

      <div className="flex flex-wrap gap-x-4 gap-y-1 text-[11px] mt-1">
        {[['Desert controls', C_DESERT], ['Disturbed quarry', C_DISTURBED],
          ['Known Li deposits', C_DEPOSIT]].map(([l, c]) => (
          <span key={l} className="flex items-center gap-1.5 text-zinc-400">
            <span className="w-2.5 h-2.5 rounded-sm" style={{ background: c as string }} />
            {l}
          </span>
        ))}
        <span className="flex items-center gap-1.5 text-zinc-500">
          <span className="w-2.5 border-t border-dashed border-zinc-500" />
          Brine sites (excluded)
        </span>
      </div>
    </div>
  )
}

type Scope = 'lithium' | 'vanadium' | 'india'

/** Which validated region, if any, contains the point being analysed. */
function regionFor(lat?: number, lon?: number) {
  if (lat === undefined || lon === undefined) return null
  for (const r of (V.coverage?.regions ?? [])) {
    const b = r.bounds
    if (lat >= b.lat_min && lat <= b.lat_max && lon >= b.lon_min && lon <= b.lon_max) {
      return r
    }
  }
  return null
}

export function ValidationCard({ lat, lon, placeName }: {
  /** Current AOI. Omitted on the dashboard, where there is no selected point. */
  lat?: number
  lon?: number
  placeName?: string | null
} = {}) {
  const [openAois, setOpenAois] = useState(false)
  const region = regionFor(lat, lon)
  // Open on the tab that matches where the user actually is. Showing Nevada
  // numbers beside an Indian analysis implies a transfer that does not exist.
  const [scope, setScope] = useState<Scope>(
    region?.scope === 'india' ? 'india' : 'lithium')
  useEffect(() => {
    if (region?.scope === 'india') setScope('india')
    else if (region?.scope === 'lithium') setScope('lithium')
  }, [region?.id])

  const VA = V.vanadium
  const IN = V.india

  return (
    <section className="@container/vcard space-y-4">
      <div className="flex flex-wrap items-center gap-3">
        <h2 className="flex items-center gap-2 text-base @[32rem]/vcard:text-xl
                       font-bold tracking-tight">
          <FlaskConical className="w-4 h-4 @[32rem]/vcard:w-5 @[32rem]/vcard:h-5 shrink-0"
                        style={{ color: C_DEPOSIT }} />
          Validation against USGS MRDS
        </h2>
        <a href="/validation_card.png" download
           className="ml-auto flex items-center gap-1.5 text-[11px] px-2.5 py-1.5 rounded-lg
                      border border-white/15 text-zinc-300 hover:bg-white/10 transition">
          <Download className="w-3.5 h-3.5" /> Slide figure (PNG)
        </a>
      </div>

      {/*
        Location awareness. Without this the panel showed Nevada results no
        matter where the user had analysed — which reads as though the
        validation applies there. It does not; validation is region-specific.
      */}
      {lat !== undefined && lon !== undefined && (
        <div className={`rounded-xl border p-3 ${
          region?.status === 'validated'
            ? 'border-emerald-400/30 bg-emerald-400/[0.07]'
            : region?.status === 'spot check'
              ? 'border-amber-400/30 bg-amber-400/[0.07]'
              : 'border-zinc-400/30 bg-zinc-400/[0.07]'}`}>
          <p className="flex items-center gap-2 text-[12px] font-semibold
                        text-zinc-100 flex-wrap">
            <MapPin className="w-3.5 h-3.5 shrink-0" />
            {placeName || `${lat.toFixed(3)}, ${lon.toFixed(3)}`}
            <span className="text-zinc-500 font-normal">—</span>
            <span className={
              region?.status === 'validated' ? 'text-emerald-300'
              : region?.status === 'spot check' ? 'text-amber-300' : 'text-zinc-400'}>
              {region ? `${region.label}: ${region.status}` : 'no validation for this region'}
            </span>
          </p>
          <p className="text-[11px] text-zinc-400 mt-1 leading-relaxed">
            {region ? region.summary : V.coverage?.outside?.summary}
          </p>
        </div>
      )}

      {/* Three separate studies, deliberately not merged: lithium has a raw
          cross-scene index, vanadium does not, and India has no usable ground
          truth. Pooling them would hide exactly those differences. */}
      <div className="flex items-center gap-1 p-0.5 rounded-lg bg-white/5 w-fit">
        {([['lithium', 'Lithium · Nevada'],
           ['vanadium', 'Vanadium · Nevada'],
           ['india', 'India']] as [Scope, string][]).map(([id, label]) => (
          <button key={id} onClick={() => setScope(id)}
            className={`px-3 py-1 rounded-md text-[12px] transition ${
              scope === id ? 'bg-white/12 text-zinc-100 font-medium'
                           : 'text-zinc-400 hover:text-zinc-200'}`}>
            {label}
          </button>
        ))}
      </div>

      {scope === 'lithium' && (
      <p className="text-sm text-zinc-400 max-w-3xl leading-relaxed">{V.headline}</p>
      )}

      {/* ---------------- vanadium ---------------- */}
      {scope === 'vanadium' && VA && (
        <div className="space-y-3">
          <p className="text-sm text-zinc-400 max-w-3xl leading-relaxed">
            {VA.separation_note}
          </p>
          <div className="grid grid-cols-1 @[26rem]/vcard:grid-cols-2
                          @[62rem]/vcard:grid-cols-4 gap-3">
            <Stat label="V-dominant sites"
                  value={`${VA.v_dominant.median_percentile}th`} accent={C_DEPOSIT}
                  sub={`median within-scene percentile · n=${VA.v_dominant.n}`} />
            <Stat label="Polymetallic sites"
                  value={`${VA.polymetallic.median_percentile}th`}
                  sub={`V is a trace associate here · n=${VA.polymetallic.n}`} />
            <Stat label="Sites scored" value={`${VA.counts.scored}`}
                  sub={`${VA.counts.masked} masked · across ${VA.aois.length} areas`} />
            <Stat label="At the ceiling"
                  value={`${VA.v_dominant.at_ceiling}`}
                  sub="scored exactly 1.000 — the normalisation ceiling, not a perfect match" />
          </div>
          <div className="rounded-xl border border-amber-400/25 bg-amber-400/5 p-4
                          text-[12px] leading-relaxed text-amber-200/85 space-y-2">
            <p><b className="text-amber-200">Black shale, unresolved.</b> {VA.gibellini_note}</p>
            <p className="text-amber-200/70">{VA.what_this_measures}</p>
          </div>
        </div>
      )}

      {/* ---------------- india ---------------- */}
      {scope === 'india' && IN && (
        <div className="space-y-3">
          <div className="flex items-center gap-2">
            <span className="text-[11px] px-2 py-0.5 rounded border border-amber-400/40
                             text-amber-300">{IN.status}</span>
          </div>
          <p className="text-sm text-zinc-300 max-w-3xl leading-relaxed">
            {IN.headline_finding}
          </p>

          <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
            <p className="text-[12px] font-medium text-zinc-300 mb-2">
              Usable rock per area
            </p>
            <div className="space-y-1.5">
              {IN.measurements.map((m: any) => (
                <div key={m.id} className="flex items-center gap-3 text-[12px]">
                  <span className="w-[190px] shrink-0 truncate text-zinc-300">{m.name}</span>
                  <div className="flex-1 h-2 rounded-full bg-white/8 overflow-hidden">
                    <div className="h-full rounded-full"
                         style={{ width: `${m.rock_pct}%`,
                                  background: m.rock_pct > 50 ? C_DEPOSIT : C_DISTURBED }} />
                  </div>
                  <span className="w-12 text-right tabular-nums text-zinc-300">
                    {m.rock_pct}%
                  </span>
                </div>
              ))}
            </div>
            <p className="text-[11px] text-zinc-500 mt-2">
              Below ~10% usable rock there is almost nothing for the index to measure.
            </p>
          </div>

          <div className="rounded-xl border border-amber-400/25 bg-amber-400/5 p-4">
            <p className="flex items-center gap-2 text-sm font-semibold text-amber-200 mb-2">
              <AlertTriangle className="w-4 h-4" /> Why this is not a validation
            </p>
            <ul className="space-y-1.5 text-[12px] leading-relaxed text-amber-200/85">
              {IN.why_not_a_validation.map((c: string) => (
                <li key={c} className="flex gap-2">
                  <span className="text-amber-300/60 shrink-0">—</span>{c}
                </li>
              ))}
            </ul>
            <p className="text-[12px] text-amber-200/70 mt-3 pt-3 border-t border-amber-400/20">
              {IN.conclusion}
            </p>
          </div>
        </div>
      )}

      {scope !== 'lithium' ? null : (<>

      <div className="grid grid-cols-1 @[26rem]/vcard:grid-cols-2
                      @[62rem]/vcard:grid-cols-4 gap-3">
        <AucRange />
        <Stat label="Enrichment, top 5%"
              value={`${M.enrichment_top5pct}×`} accent={C_DEPOSIT}
              sub="deposits are this many times more concentrated in the top 5% than chance" />
        <Stat label="Spatial permutation"
              value={`p = ${M.permutation_p.toFixed(4)}`}
              sub={`relocating the same ${M.permutation_n} points at random, ${M.permutation_draws.toLocaleString()} draws`} />
        <Stat label="Sites scored"
              value={`${V.counts.positives_scored}`}
              sub={`non-brine. ${V.counts.brine} brine and ${V.counts.excluded_plant} plant excluded; ${V.counts.background_pixels.toLocaleString()} background pixels`} />
      </div>

      <Distribution />

      {/* Deliberately always visible — see the note at the top of this file. */}
      <div className="rounded-xl border border-amber-400/25 bg-amber-400/5 p-4">
        <p className="flex items-center gap-2 text-sm font-semibold text-amber-200 mb-2">
          <AlertTriangle className="w-4 h-4" /> What this does not establish
        </p>
        <ul className="space-y-1.5 text-[12px] leading-relaxed text-amber-200/85">
          {V.caveats.map((c: string) => (
            <li key={c} className="flex gap-2">
              <span className="text-amber-300/60 shrink-0">—</span>{c}
            </li>
          ))}
        </ul>
      </div>

      {/*
        Per-site provenance. The question this answers is "how do you know
        there is lithium there at all?" — and the answer is not our index, it
        is the USGS record for that site. Scholar/news are prefilled searches,
        not specific articles: a search URL cannot rot, and it does not put
        words in any publication's mouth.
      */}
      <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
        <p className="text-sm font-medium text-zinc-200">The sites we tested against</p>
        <p className="text-[11px] text-zinc-500 mt-0.5 mb-3">
          Each one is a catalogued USGS occurrence — click through to the primary record.
        </p>

        <div className="space-y-1.5">
          {[...V.deposits, ...V.brine.map((b: any) => ({ ...b, brine: true }))]
            .sort((a: any, b: any) => (b.value ?? 0) - (a.value ?? 0))
            .map((r: any) => (
            <div key={r.site}
                 className="flex flex-wrap items-baseline gap-x-2 gap-y-1 py-1.5
                            border-t border-white/5 first:border-0">
              <span className="text-[12px] text-zinc-200">{r.site}</span>
              {r.dev && (
                <span className="text-[11px] text-zinc-500">{r.dev}</span>
              )}
              {r.brine && (
                <span className="text-[11px] px-1.5 rounded bg-white/8 text-zinc-400">
                  brine — excluded
                </span>
              )}
              <span className="text-[11px] tabular-nums text-zinc-400 ml-auto">
                {r.value?.toFixed(3) ?? '—'}
              </span>
              <span className="flex items-center gap-2 basis-full @[26rem]/vcard:basis-auto">
                {r.url && (
                  <a href={r.url} target="_blank" rel="noreferrer"
                     className="flex items-center gap-1 text-[11px] hover:underline"
                     style={{ color: C_DEPOSIT }}>
                    USGS record <ExternalLink className="w-3 h-3" />
                  </a>
                )}
                {r.scholar && (
                  <a href={r.scholar} target="_blank" rel="noreferrer"
                     className="text-[11px] text-zinc-500 hover:text-zinc-300 hover:underline">
                    research
                  </a>
                )}
                {r.news && (
                  <a href={r.news} target="_blank" rel="noreferrer"
                     className="text-[11px] text-zinc-500 hover:text-zinc-300 hover:underline">
                    news
                  </a>
                )}
              </span>
            </div>
          ))}
        </div>

        <div className="flex flex-wrap gap-x-4 gap-y-1 mt-3 pt-3 border-t border-white/10">
          {V.references?.map((ref: any) => (
            <a key={ref.url} href={ref.url} target="_blank" rel="noreferrer"
               className="flex items-center gap-1 text-[11px] text-zinc-400 hover:text-zinc-200 hover:underline"
               title={ref.note}>
              {ref.label} <ExternalLink className="w-3 h-3" />
            </a>
          ))}
        </div>
      </div>

      </>)}

      {scope === 'lithium' && (
      <details className="rounded-xl border border-white/10 bg-white/[0.03]"
               open={openAois} onToggle={e => setOpenAois((e.target as HTMLDetailsElement).open)}>
        <summary className="flex items-center gap-2 px-4 py-3 cursor-pointer text-sm
                            text-zinc-300 list-none marker:content-['']">
          Per-area measurements ({V.aoi_table.length} areas)
          <ChevronDown className={`w-4 h-4 ml-auto transition-transform ${openAois ? 'rotate-180' : ''}`} />
        </summary>
        <div className="overflow-x-auto px-4 pb-4">
          <table className="w-full text-[12px]">
            <thead className="text-zinc-500">
              <tr className="text-left">
                <th className="py-1.5 font-medium">Area</th>
                <th className="font-medium">Type</th>
                <th className="font-medium text-right hidden @[30rem]/vcard:table-cell">rock %</th>
                <th className="font-medium text-right hidden @[26rem]/vcard:table-cell">median</th>
                <th className="font-medium text-right">p95</th>
                <th className="font-medium text-right">max</th>
              </tr>
            </thead>
            <tbody>
              {V.aoi_table.map((a: any) => (
                <tr key={a.id} className="border-t border-white/5">
                  <td className="py-1.5 text-zinc-300">{a.name}</td>
                  <td className="text-zinc-500">{a.kind}</td>
                  <td className="text-right tabular-nums text-zinc-400 hidden @[30rem]/vcard:table-cell">{a.rock_pct}</td>
                  <td className="text-right tabular-nums text-zinc-400 hidden @[26rem]/vcard:table-cell">{a.median}</td>
                  <td className="text-right tabular-nums text-zinc-400">{a.p95}</td>
                  <td className="text-right tabular-nums text-zinc-200 font-medium">{a.max}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="text-[11px] text-zinc-500 mt-2 leading-relaxed">
            {V.rules.deposit_value}. {V.rules.null_policy}. Rules were frozen before
            any run, and the engine was used unchanged.
          </p>
        </div>
      </details>
      )}
    </section>
  )
}
